CREATE FUNCTION lablens_guard_dataset() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP = 'UPDATE' AND OLD.status = 'ready' THEN RAISE EXCEPTION 'Dataset snapshots are immutable'; END IF;
 IF TG_OP = 'UPDATE' AND NEW.status = 'ready' THEN
  IF (SELECT count(*) FROM dataset_columns WHERE dataset_id=NEW.id) <> 2 OR
     (SELECT count(*) FROM dataset_points WHERE dataset_id=NEW.id) <> NEW.row_count OR
     (SELECT min(point_index) FROM dataset_points WHERE dataset_id=NEW.id) <> 0 OR
     (SELECT max(point_index) FROM dataset_points WHERE dataset_id=NEW.id) <> NEW.row_count-1 THEN
    RAISE EXCEPTION 'Dataset snapshot invariant failed';
  END IF;
 END IF;
 IF TG_OP = 'DELETE' AND EXISTS (SELECT 1 FROM projects WHERE id=OLD.project_id AND status='active') THEN
  RAISE EXCEPTION 'Delete the project to remove a dataset';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$

CREATE FUNCTION lablens_guard_dataset_child() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE parent_id uuid;
BEGIN
 parent_id := CASE WHEN TG_OP='DELETE' THEN OLD.dataset_id ELSE NEW.dataset_id END;
 IF TG_OP='UPDATE' AND OLD.dataset_id <> NEW.dataset_id THEN RAISE EXCEPTION 'Cannot move dataset rows'; END IF;
 IF EXISTS (SELECT 1 FROM dataset_versions d JOIN projects p ON p.id=d.project_id WHERE d.id=parent_id AND d.status='ready' AND p.status='active') THEN
  RAISE EXCEPTION 'Ready dataset rows are immutable';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$

CREATE FUNCTION lablens_guard_analysis() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.sealed THEN RAISE EXCEPTION 'Analysis snapshots are immutable'; END IF;
 IF TG_OP='UPDATE' AND NEW.sealed AND NEW.status='succeeded' THEN
   IF NOT EXISTS (SELECT 1 FROM analysis_results WHERE analysis_id=NEW.id) OR
      (SELECT count(*) FROM analysis_point_results WHERE analysis_id=NEW.id) <> (SELECT row_count FROM dataset_versions WHERE id=NEW.dataset_id) THEN
     RAISE EXCEPTION 'Analysis snapshot invariant failed';
   END IF;
 END IF;
 IF TG_OP='DELETE' AND EXISTS (SELECT 1 FROM projects WHERE id=OLD.project_id AND status='active') THEN
  RAISE EXCEPTION 'Delete the project to remove an analysis';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$

CREATE FUNCTION lablens_guard_analysis_child() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE parent_id uuid;
BEGIN
 parent_id := CASE WHEN TG_OP='DELETE' THEN OLD.analysis_id ELSE NEW.analysis_id END;
 IF TG_OP='UPDATE' AND OLD.analysis_id <> NEW.analysis_id THEN RAISE EXCEPTION 'Cannot move analysis rows'; END IF;
 IF EXISTS (SELECT 1 FROM analyses a JOIN projects p ON p.id=a.project_id WHERE a.id=parent_id AND a.sealed AND p.status='active') THEN
  RAISE EXCEPTION 'Completed analysis rows are immutable';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$
